def refs(ids):
    return ' '.join(f'<a class="source" href="{E(SOURCES[k][1], quote=True)}" rel="noopener noreferrer">{E(k)}</a>' for k in ids.split())


def table(title, headers, rows, note='Status labels: Verified = official statement read directly; Owner-supplied = figure from the owner, rounded to $10, not independently confirmed; Projection / Assumption = model output of labeled assumptions; Guidance = analysis; Missing = deliberately blank, never zero; Synthetic = invented illustration.'):
    out = f'<section class="table-section"><h2>{E(title)}</h2><p class="table-note">{E(note)}</p><div class="table-scroll" tabindex="0" aria-label="{E(title)}"><table><caption class="sr-only">{E(title)}</caption><thead><tr>' + ''.join(f'<th scope="col">{E(x)}</th>' for x in headers + ['Status', 'Official source / scope']) + '</tr></thead><tbody>'
    for cells, status, ids in rows:
        out += '<tr>' + ''.join('<td aria-label="Not verified; intentionally blank"></td>' if x is None else f'<td>{E(str(x))}</td>' for x in cells) + f'<td><span class="badge {status.lower()}">{E(status)}</span></td><td>' + refs(ids) + '</td></tr>'
    return out + '</tbody></table></div></section>'


def callout(title, text, kind='info'):
    return f'<aside class="callout {kind}"><strong>{E(title)}</strong><p>{E(text)}</p></aside>'


def cards(items):
    return '<div class="cards">' + ''.join(f'<a class="card" href="{E(url)}"><small>{E(label)}</small><strong>{E(title)}</strong><span>{E(text)} →</span></a>' for label, title, text, url in items) + '</div>'


